public class TFMMethodParameterAttribute extends SysAttribute implements SysExtensionIAttribute
{
    MethodName          method;
    str                 parmType;


}

Method.Source:
void new(MethodName _method, str _parmType)
{
    super();

    method = _method;
    parmType = _parmType;

}

public MethodName parmMethodName(MethodName _method = method)
{
    method = _method;

    return method;
}

public str parmParameterType(str _parmType = parmType)
{
    parmType = _parmType;

    return parmType;
}
